import {team} from './engine.js?v=3.8.0';
import {canChange} from './commands.js?v=3.8.0';
import {teamContact,discussionWait,PREFERENCES} from './career-plan.js?v=3.8.0';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function discussionsView(s){
 const d=s.careerPlan.discussions,e=d.teamwork,contact=teamContact(s),writable=canChange(s);
 const button=(label,topic,blocked=false)=>`<button class="secondary" data-action="talk:${topic}" ${!writable||blocked?'disabled':''}>${esc(label)}</button>`;
 const wait=actor=>discussionWait(s,actor)?`Nouvel échange dans ${discussionWait(s,actor)} jour(s).`:'Disponible pour un échange.';
 const reply=actor=>{const h=d.history.findLast(h=>h.actor===actor);return h?`<p class="data-note"><b>${esc(h.person)} · S${h.season}, J${h.day}</b><br>${esc(h.text)}</p>`:'<p class="muted">Aucun échange enregistré.</p>';};
 return `<section class="panel discussions"><p class="eyebrow">ÉCHANGES SPORTIFS</p><h2>Votre entourage sur le terrain</h2><p>Donnez une direction à votre carrière et suivez ce qui a été convenu.</p>${!writable?`<p class="data-note">${s.retired?'Carrière terminée : les échanges restent consultables.':'Terminez le match ou la décision en cours pour discuter.'}</p>`:''}
 <div class="discussion-grid"><article><h3>Coach · ${esc(team(s).coach)}</h3><p>Clarifiez la concurrence, les minutes envisagées et votre évaluation.</p>${button('Comprendre les attentes','coach-plan',!!discussionWait(s,'coach'))}<p class="muted">${wait('coach')}</p>${reply('coach')}</article>
 <article><h3>Agent · ${esc(s.life.people.agent.name)}</h3><p>Votre priorité : <b>${esc(PREFERENCES[s.careerPlan.preference])}</b>. Elle guide la présentation des prochaines offres.</p><div class="button-row">${Object.entries(PREFERENCES).map(([key,label])=>button(label,'agent-'+key,!!discussionWait(s,'agent'))).join('')}</div><p class="muted">${wait('agent')}</p>${reply('agent')}</article>
 <article><h3>Coéquipier · ${esc(contact?.name||'Indisponible')}</h3><p>Préparez le jeu collectif : 2 matchs joués et 3 journées vidéo en 21 jours. Cohésion +3 au bilan si l’objectif est rempli, sans malus en cas d’échec.</p>${button('Proposer ce travail collectif','team-work',!!e||!contact||!!discussionWait(s,'team'))}<p class="muted">${e?'Un engagement est déjà en cours.':wait('team')}</p>${e?`<div class="data-note"><b>Avec ${esc(e.person)} · bilan dans ${Math.max(0,e.due+1-s.day)} jour(s)</b><p>${e.games.length}/2 matchs · ${e.videoDays}/3 journées vidéo.</p><p>Choisissez « Vidéo et lecture du jeu » dans votre programme ci-dessous. Activité actuelle : ${s.activity==='video'?'vidéo, le travail peut avancer chaque jour où vous êtes disponible':'autre activité, aucune journée vidéo ne sera comptée'}.</p></div>`:''}${reply('team')}</article></div>
 <details><summary>Historique des échanges · ${d.history.length}</summary>${[...d.history].reverse().map(h=>`<article class="discussion-entry"><p><b>${esc(h.title)} · ${esc(h.person)}</b><br><small>S${h.season}, J${h.day} · ${esc(team(s,h.team)?.name||h.team)}</small></p><p>${esc(h.text)}</p></article>`).join('')||'<p>Vos prochains échanges seront conservés ici.</p>'}<p class="muted">Les 40 derniers échanges sont conservés ici ; les précédents restent dans votre journal.</p></details></section>`;
}
